// The diagnostic policy receives observations only. Hidden world stays in Mission.
export const TYPES=['healthy','loose','delamination','crack'];
export const LABELS=['Healthy','Loose fastener','Delamination','Microcrack'];
export const N=32;
export const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
export const panelName=i=>`${String.fromCharCode(65+Math.floor(i/8))}${i%8+1}`;
export function random(seed){let s=seed>>>0;return()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function gaussian(r){return Math.sqrt(-2*Math.log(Math.max(1e-8,r())))*Math.cos(2*Math.PI*r())}
export function adjacent(i){return [i%8?i-1:-1,i%8<7?i+1:-1,i>=8?i-8:-1,i<24?i+8:-1].filter(x=>x>=0)}
// Normalised sensor features: resonance shift, damping, temperature, strain.
export function signature(type,s){return type===1?[.85*s,.25*s,.16*s,.24*s]:type===2?[.36*s,.86*s,.62*s,.36*s]:type===3?[.62*s,.46*s,.24*s,.95*s]:[0,0,0,0]}
export class Policy{
 constructor(){this.obs=Array.from({length:N},()=>[]);this.beliefs=Array.from({length:N},()=>({p:[.79,.07,.07,.07],risk:.21,type:0,confidence:.79,severity:0,uncertainty:.48}));}
 observe(o){this.obs[o.panel].push(o);this.update(o.panel)}
 update(i){const readings=this.obs[i].slice(-4);const weights=[];for(let t=0;t<4;t++)for(const s of (t?[.25,.45,.65,.85,1]:[0])){let log=Math.log(t?.07/5:.79);for(const o of readings){const mu=signature(t,s);o.features.forEach((v,k)=>{if(v!==null)log-=.5*((v-mu[k])/(o.noise+.06))**2})}weights.push({t,s,log})}const max=Math.max(...weights.map(x=>x.log));let sum=0,p=[0,0,0,0],sev=0;weights.forEach(w=>{w.w=Math.exp(w.log-max);sum+=w.w;p[w.t]+=w.w;sev+=w.s*w.w});p=p.map(x=>x/sum);const type=p.indexOf(Math.max(...p));this.beliefs[i]={p,risk:1-p[0],type,confidence:p[type],severity:sev/sum,uncertainty:-p.reduce((s,v)=>s+(v?v*Math.log(v):0),0)/Math.log(4)};}
 next(strategy='active',reserved=[]){const available=Array.from({length:N},(_,i)=>i).filter(i=>!reserved.includes(i)&&this.obs[i].length<4);if(!available.length)return null;if(strategy==='sequential')return available.sort((a,b)=>this.obs[a].length-this.obs[b].length||a-b)[0];return available.sort((a,b)=>this.priority(b)-this.priority(a))[0]}
 priority(i){const b=this.beliefs[i],n=this.obs[i].length;const neighbor=Math.max(0,...adjacent(i).map(j=>this.beliefs[j].risk-.21));return n===0?1.1+neighbor*.8: b.uncertainty*1.7+b.risk*(1-b.confidence)*.8-n*.22;}
 reason(i){return this.obs[i].length?`Resolve ${Math.round(this.beliefs[i].uncertainty*100)}% uncertainty with a repeat measurement.`:adjacent(i).some(j=>this.beliefs[j].risk>.6)?'Inspect next to an anomalous panel to test the damage boundary.':'Expand coverage: this panel has no measurements yet.'}
 clear(i){this.obs[i]=[];this.beliefs[i]={p:[.79,.07,.07,.07],risk:.21,type:0,confidence:.79,severity:0,uncertainty:.48}}
}
export class Mission{
 #world;
 constructor(config={}){this.config={seed:2026,noise:.08,budget:52,growth:true,sensors:[true,true,true,true],defects:[{panel:11,type:2,severity:.7},{panel:22,type:1,severity:.8}],...config};this.rng=random(this.config.seed);this.#world=Array.from({length:N},()=>({type:0,severity:0,isolated:false}));for(const d of this.config.defects)this.#world[d.panel]={...d,isolated:false};this.policy=new Policy;this.robots=[{name:'ECHO–01',role:'Survey',energy:100,panel:0,online:true,measurements:0},{name:'ECHO–02',role:'Verification',energy:100,panel:31,online:true,measurements:0}];this.count=0;this.time=0;this.energy=0;this.logs=[];this.repairs=[];this.latest=null;this.status='ready';this.revealed=false;this.log('Mission ready. Hidden scenario sealed.');}
 log(text){this.logs.unshift({time:this.time,text});this.logs=this.logs.slice(0,100)}
 measure(panel,robot,verification=false){if(!Number.isInteger(panel)||panel<0||panel>=N)throw Error('Invalid panel');if(!robot?.online||robot.energy<4)throw Error('Robot unavailable');if(!verification&&this.count>=this.config.budget)throw Error('Measurement budget exhausted');const w=this.#world[panel];const mu=signature(w.type,w.severity);const features=mu.map((v,k)=>this.config.sensors[k]?v+gaussian(this.rng)*this.config.noise:null);const distance=Math.abs(robot.panel%8-panel%8)+Math.abs(Math.floor(robot.panel/8)-Math.floor(panel/8));const cost=1.6+distance*.12;robot.energy=clamp(robot.energy-cost,0,100);this.energy+=cost;robot.panel=panel;robot.measurements++;this.count++;this.time+=2+distance*.3;const o={panel,features,noise:this.config.noise,at:this.time,robot:robot.name};this.policy.observe(o);this.latest=o;if(this.config.growth&&!verification)this.grow(.0025);return o;}
 step(strategy='active'){if(this.revealed)throw Error('Reset the scenario after revealing truth');if(this.count>=this.config.budget){this.status='complete';return false}const candidates=this.robots.filter(r=>r.online&&r.energy>=4);if(!candidates.length){this.status='blocked';this.log('No operational robot. Restore a robot to continue.');return false}let panel=this.policy.next(strategy);if(panel===null){this.status='complete';return false}const robot=candidates.sort((a,b)=>{const dist=r=>Math.abs(r.panel%8-panel%8)+Math.abs((r.panel/8|0)-(panel/8|0));return dist(a)-dist(b)||b.energy-a.energy})[0];const reason=this.policy.reason(panel);this.measure(panel,robot);this.status=this.count>=this.config.budget?'complete':'running';this.log(`${robot.name} · ${panelName(panel)}. ${reason}`);return true;}
 grow(rate){for(const w of this.#world)if(w.type&&!w.isolated)w.severity=clamp(w.severity+rate*(w.type===3?1.5:1)*(w.loadFactor??1));}
 cycle(){this.grow(.09);this.time+=30;this.log('Thermal cycle applied. Unisolated damage evolved in the simulator.');}
 toggleRobot(i){this.robots[i].online=!this.robots[i].online;this.log(`${this.robots[i].name} ${this.robots[i].online?'restored':'offline; tasks reassigned to remaining robot'}.`);}
 repair(panel,action){if(this.revealed)throw Error('Reset after truth reveal to continue a blind mission');const r=this.robots.find(r=>r.online&&r.energy>=20);if(!r)throw Error('An online robot with at least 20% energy is required');const actions={tighten:1,patch:2,brace:3,isolate:-1,unload:-2,inspect:0};if(!(action in actions))throw Error('Invalid action');const w=this.#world[panel],before=this.policy.beliefs[panel].risk;if(action==='inspect'){this.measure(panel,r,true);this.log(`Additional inspection at ${panelName(panel)}.`);return}r.energy-=9;this.energy+=9;this.time+=12;const success=actions[action]===w.type&&this.rng()>.18;if(action==='isolate'){w.isolated=true;}else if(action==='unload'){w.loadFactor=.4;}else if(success){w.severity*=.12;if(w.severity<.12){w.type=0;w.severity=0}}else{w.severity*=.96}this.policy.clear(panel);for(let j=0;j<3;j++)this.measure(panel,r,true);const b=this.policy.beliefs[panel];const result=action==='isolate'?'Isolated; existing damage remains':action==='unload'?'Load reduced; growth slowed, damage remains':b.risk<.35?'Verification passed':'Residual anomaly; revise diagnosis';this.repairs.unshift({panel,action,before,after:b.risk,result});this.log(`${panelName(panel)} · ${action}. ${result}.`);return result;}
 truth(){this.revealed=true;this.status='revealed';this.log('Ground truth revealed. Blind evaluation closed.');return this.#world.map(w=>({...w}));}
 evaluate(){let tp=0,fp=0,fn=0,tn=0,typeCorrect=0;this.#world.forEach((w,i)=>{const predicted=this.policy.beliefs[i].risk>.65;const actual=w.type>0&&w.severity>.12;if(actual&&predicted){tp++;if(this.policy.beliefs[i].type===w.type)typeCorrect++}else if(actual)fn++;else if(predicted)fp++;else tn++});return{tp,fp,fn,tn,typeCorrect,recall:tp+fn?tp/(tp+fn):1,precision:tp+fp?tp/(tp+fp):null,measurements:this.count,energy:this.energy,time:this.time,coverage:this.policy.obs.filter(x=>x.length).length/N};}
 snapshot(){return{config:{...this.config,defects:this.revealed?this.config.defects:undefined},status:this.status,count:this.count,time:this.time,energy:this.energy,robots:this.robots,beliefs:this.policy.beliefs,observations:this.policy.obs,repairs:this.repairs,logs:this.logs,truthRevealed:this.revealed,...(this.revealed?{evaluation:this.evaluate()}: {})};}
}
export function benchmark({trials=40,budget=40,noise=.1}={}){const totals={active:[],sequential:[]};for(let seed=1;seed<=trials;seed++){const rng=random(seed*17),p=Math.floor(rng()*N),q=(p+1+Math.floor(rng()*(N-1)))%N;const defects=[{panel:p,type:1+Math.floor(rng()*3),severity:.45+rng()*.5},{panel:q,type:1+Math.floor(rng()*3),severity:.45+rng()*.5}];for(const strategy of ['active','sequential']){const m=new Mission({seed,defects,budget,noise,growth:false});while(m.step(strategy)){}totals[strategy].push(m.evaluate())}}const average=rows=>Object.fromEntries(['recall','fp','fn','energy','time','coverage','measurements'].map(key=>[key,rows.reduce((s,r)=>s+r[key],0)/rows.length]));return{trials,budget,noise,growth:false,active:average(totals.active),sequential:average(totals.sequential),raw:totals};}
